#!/bin/bash
# replay_all_suite_corpora.sh — regenerate cpu/coverage_suite_*.dat for every
# already-recorded corpus_suite_*.json, in parallel, EXCLUDING
# riscv_csr_test on purpose (its .dat is never generated by this script, so
# it can never leak into an aggregate_suite_coverage.py run afterward --
# used to measure what the 171-test suite achieves WITHOUT its one
# deterministic CSR-sweep test, i.e. 170 tests).
#
# Idempotent/resumable: replay_suite_corpus_dat.py skips any corpus whose
# .dat already exists, so re-running after an interruption only does the
# remaining work.
#
# Usage:
#   bash replay_all_suite_corpora.sh [n_parallel, default 24]
set -e
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${IBEX_VENV:-$HOME/ibex_env}/bin/activate"
cd "$SCRIPT_DIR"

N_PARALLEL="${1:-24}"

echo "=== Replaying corpus_suite_*.json (EXCLUDING riscv_csr_test) with $N_PARALLEL parallel workers ==="
ls corpus_suite_*.json | grep -v riscv_csr_test | xargs -P "$N_PARALLEL" -I{} \
    python3 replay_suite_corpus_dat.py {}

echo ""
echo "=== Done. .dat files present (should be 170, riscv_csr_test excluded): ==="
ls ../../cpu/coverage_suite_*.dat 2>/dev/null | grep -v riscv_csr_test | wc -l
echo "(if a riscv_csr_test .dat exists from an OLDER run, move/delete it before aggregating, or aggregate_suite_coverage.py will still include it)"
